#include <stdarg.h>
#include <unistd.h>

int	ft_putchar_n(char c);
int	ft_putstr_n(char *s);
int	ft_putnbr_n(int n);

int	conversion(char c, va_list *args)
{
	if (c == 'c')
		return (ft_putchar_n((char)va_arg(*args, int)));
	if (c == 's')
		return (ft_putstr_n(va_arg(*args, char *)));
	if (c == 'd')
		return (ft_putnbr_n(va_arg(*args, int)));
	return (ft_putchar_n(c));
}

int	mini_printf(const char *format, ...)
{
	va_list	args;
	int		total;

	va_start(args, format);
	total = 0;
	while (*format)
	{
		if (*format == '%' && *(format + 1))
			total += conversion(*(++format), &args);
		else
			total += ft_putchar_n(*format);
		format++;
	}
	va_end(args);
	return (total);
}

