#include <unistd.h>

void	afficher_bits(unsigned char c)
{
	int		i;
	char	b;

	i = 7;
	while (i >= 0)
	{
		b = ((c >> i) & 1) + '0';
		write(1, &b, 1);
		i--;
	}
	write(1, "\n", 1);
}

