#include <pthread.h>
#include <stdio.h>

int				g_compteur = 0;
pthread_mutex_t	g_verrou;

void	*ajouter(void *arg)
{
	int	i;

	(void)arg;
	i = 0;
	while (i < 100000)
	{
		pthread_mutex_lock(&g_verrou);
		g_compteur++;
		pthread_mutex_unlock(&g_verrou);
		i++;
	}
	return (NULL);
}

int	main(void)
{
	pthread_t	t1;
	pthread_t	t2;

	pthread_mutex_init(&g_verrou, NULL);
	pthread_create(&t1, NULL, ajouter, NULL);
	pthread_create(&t2, NULL, ajouter, NULL);
	pthread_join(t1, NULL);
	pthread_join(t2, NULL);
	pthread_mutex_destroy(&g_verrou);
	printf("%d\n", g_compteur);
	return (0);
}

